from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class RfTemperatureSupervision(SchemaObject):
    sensor_name = SchemaField(name='sensorName')
    temperature_value = SchemaField(name='temperatureValue')

    def __init__(self, sensor_name, temperature_value):
        self.sensor_name = sensor_name
        self.temperature_value = temperature_value

        super(RfTemperatureSupervision, self).__init__()


class RfEthernetPacketMonitoring(SchemaObject):
    port = SchemaField(name='port')
    start_time = SchemaField(name='startTime')
    received_errored_frames = SchemaField(name='receivedErroredFrames')
    received_frames = SchemaField(name='receivedFrames')
    received_multicast_frames = SchemaField(name='receivedMulticastFrames')
    received_octets = SchemaField(name='receivedOctets')
    received_unknown_type_frames = SchemaField(name='receivedUnknownTypeFrames')
    received_unknown_vlan_frames = SchemaField(name='receivedUnknownVlanFrames')
    transmitted_frames = SchemaField(name='transmittedFrames')
    transmitted_multicast_frames = SchemaField(name='transmittedMulticastFrames')
    transmitted_octets = SchemaField(name='transmittedOctets')

    def __init__(self, port, start_time, received_errored_frames, received_frames, received_multicast_frames,
                 received_octets, received_unknown_type_frames, received_unknown_vlan_frames, transmitted_frames,
                 transmitted_multicast_frames, transmitted_octets):
        self.port = port
        self.start_time = start_time
        self.received_errored_frames = received_errored_frames
        self.received_frames = received_frames
        self.received_multicast_frames = received_multicast_frames
        self.received_octets = received_octets
        self.received_unknown_type_frames = received_unknown_type_frames
        self.received_unknown_vlan_frames = received_unknown_vlan_frames
        self.transmitted_frames = transmitted_frames
        self.transmitted_multicast_frames = transmitted_multicast_frames
        self.transmitted_octets = transmitted_octets

        super(RfEthernetPacketMonitoring, self).__init__()


class RfStatDiagTestResultResults(SchemaObject):
    actual_start_time = SchemaField(name='actualStartTime')
    actual_stop_time = SchemaField(name='actualStopTime')
    result = SchemaField(name='result')
    uptime = SchemaField(name='uptime')
    test_outcome = SchemaField(name='testOutcome')
    rf_temperature_supervision = SchemaField(name='rfTemperatureSupervision',
                                             many=True,
                                             klass=RfTemperatureSupervision)
    rf_ethernet_packet_monitoring = SchemaField(name='ethernetPacketMonitoring',
                                                many=True,
                                                klass=RfEthernetPacketMonitoring)
    test_outcome_additional_info = SchemaField(name='testOutcomeAdditionalInfo')

    def __init__(self, actual_start_time, actual_stop_time, result, uptime, test_outcome, rf_temperature_supervision,
                 rf_ethernet_packet_monitoring, test_outcome_additional_info):
        self.actual_start_time = actual_start_time
        self.actual_stop_time = actual_stop_time
        self.result = result
        self.uptime = uptime
        self.test_outcome = test_outcome
        self.rf_temperature_supervision = rf_temperature_supervision
        self.rf_ethernet_packet_monitoring = rf_ethernet_packet_monitoring
        self.test_outcome_additional_info = test_outcome_additional_info

        super(RfStatDiagTestResultResults, self).__init__()


class RfDiagTestResults(SchemaObject):
    dist_name = SchemaField(name='distName', not_null=True)
    radio_id = SchemaField(name='radioId', not_null=True)
    results = SchemaField(name='generalTestInfo', klass=RfStatDiagTestResultResults)

    def __init__(self, dist_name, radio_id, results):
        self.dist_name = dist_name
        self.radio_id = radio_id
        self.results = results

        super(RfDiagTestResults, self).__init__()


class RFStatDiagTestResult(SchemaObject):
    bts_id = SchemaField(name='btsId', not_null=True)
    bts_name = SchemaField(name='btsName', not_null=True)
    rf_statistics_diagnostic_test_results = SchemaField(name='rfStatisticsDiagnosticTestResults',
                                                        klass=RfDiagTestResults,
                                                        many=True,
                                                        not_null=True)

    def __init__(self, bts_id, bts_name, rf_statistics_diagnostic_test_results):
        self.bts_id = bts_id
        self.bts_name = bts_name
        self.rf_statistics_diagnostic_test_results = rf_statistics_diagnostic_test_results

        super(RFStatDiagTestResult, self).__init__()
